const j = $input.first().json || {};
const ACTIONS = ['REQUEST_CHECK_IN', 'REQUEST_CHECK_OUT', 'LOCATION', 'CANCEL'];
const telegram_id = String(j.telegram_id == null ? '' : j.telegram_id).trim();
const action = String(j.action || '').trim().toUpperCase();
let location = null;
const raw = j.location_json;
if (raw && typeof raw === 'object') location = raw;
else if (raw && String(raw).trim()) { try { location = JSON.parse(String(raw)); } catch (e) { location = null; } }
const fw = j.is_forwarded === true || String(j.is_forwarded).toLowerCase() === 'true';
return [{ json: {
  valid: telegram_id.length > 0 && ACTIONS.indexOf(action) >= 0,
  action,
  telegram_id,
  chat_id: String(j.chat_id || telegram_id).trim(),
  update_id: String(j.update_id || ''),
  location,
  message_date: Number(j.message_date) || 0,
  is_forwarded: fw,
} }];

function uuidv4() { const h = '0123456789abcdef'; let s = ''; for (let i = 0; i < 36; i++) { if (i === 8 || i === 13 || i === 18 || i === 23) { s += '-'; continue; } if (i === 14) { s += '4'; continue; } let r = Math.floor(Math.random() * 16); if (i === 19) r = (r & 3) | 8; s += h[r]; } return s; }
const inp = $('Normalize Input').first().json;
function rows(name, key) { return $(name).all().map(function (i) { return i.json; }).filter(function (r) { return r && r[key]; }); }
const emp = rows('Get Employee', 'employee_id')[0];
const schedRow = rows('Get Schedule', 'employee_id').filter(function (r) { return String(r.active) !== 'false'; })[0];
const actives = rows('Get Active Shift', 'shift_id').sort(function (a, b) { return String(a.check_in_time).localeCompare(String(b.check_in_time)); });
const byUpdate = rows('Get Shift By Update', 'shift_id')[0];
const dlg = rows('Get Geo Request', 'telegram_id')[0];
const S = {};
rows('Get Settings', 'setting_key').forEach(function (r) { S[r.setting_key] = r.setting_value; });
function num(v, d) { const n = Number(v); return Number.isFinite(n) ? n : d; }
const LAT = num(S.work_lat, 51.161613);
const LON = num(S.work_lon, 71.417481);
const RADIUS = num(S.work_radius_m, 150);
const TTL = num(S.geo_request_ttl_min, 10);
const tz = S.timezone || 'Asia/Almaty';
const now = DateTime.now().setZone(tz);
const nowIso = now.toISO();
const MAIN_MENU = [['🟢 Начать работу', '🔴 Завершить работу'], ['🐟 Fish Coins', '📊 Моя статистика'], ['🏖 Отпуск', '🤒 Больничный'], ['📅 Встреча', '👤 Мой профиль'], ['🤖 Спросить TUNA']];
const LOC_KB = [['📍 Отправить геолокацию'], ['❌ Отмена']];
const active = actives[0];
const curStatus = active ? 'WORKING' : 'NOT_STARTED';

function reply(text, kbType, extra) {
  return Object.assign({ action: 'REPLY', chat_id: inp.chat_id, text: text, keyboard_type: kbType, keyboard: kbType === 'location' ? LOC_KB : (kbType === 'main_menu' ? MAIN_MENU : []), status: curStatus, distance_m: null, coin_result: null }, extra || {});
}
function out(op, r, extra) { return [{ json: Object.assign({ op: op, reply: r, telegram_id: inp.telegram_id, now_iso: nowIso }, extra || {}) }]; }
function haversine(lat1, lon1, lat2, lon2) {
  const R = 6371000;
  const toR = function (x) { return x * Math.PI / 180; };
  const dLat = toR(lat2 - lat1);
  const dLon = toR(lon2 - lon1);
  const h = Math.pow(Math.sin(dLat / 2), 2) + Math.cos(toR(lat1)) * Math.cos(toR(lat2)) * Math.pow(Math.sin(dLon / 2), 2);
  return 2 * R * Math.asin(Math.min(1, Math.sqrt(h)));
}
function fmtMin(m) { const h = Math.floor(m / 60); const mm = m % 60; return (h ? h + ' ч ' : '') + mm + ' мин'; }

if (!emp) return out('REPLY_ONLY', reply('Вы ещё не зарегистрированы. Отправьте /start, чтобы пройти регистрацию.', 'remove', { result: 'NOT_REGISTERED' }));

if (inp.action === 'CANCEL') {
  return out('CLEAR_REQUEST', reply('Запрос геолокации отменён.', 'main_menu', { result: 'CANCELLED' }));
}

if (inp.action === 'REQUEST_CHECK_IN' || inp.action === 'REQUEST_CHECK_OUT') {
  const isIn = inp.action === 'REQUEST_CHECK_IN';
  if (isIn && active) return out('REPLY_ONLY', reply('У вас уже есть активная смена с ' + DateTime.fromISO(active.check_in_time).setZone(tz).toFormat('dd.MM HH:mm') + '. Сначала завершите её кнопкой «🔴 Завершить работу».', 'main_menu', { result: 'ALREADY_WORKING' }));
  if (!isIn && !active) return out('REPLY_ONLY', reply('У вас нет активной смены. Чтобы начать, нажмите «🟢 Начать работу».', 'main_menu', { result: 'NO_ACTIVE_SHIFT' }));
  const expires = now.plus({ minutes: TTL }).toISO();
  return out('SET_REQUEST', reply((isIn ? 'Чтобы начать смену' : 'Чтобы завершить смену') + ', отправьте свою текущую геолокацию кнопкой «📍 Отправить геолокацию» в течение ' + TTL + ' мин. Пересланные и старые геолокации не принимаются.', 'location', { result: 'LOCATION_REQUESTED' }), {
    flow: isIn ? 'CHECK_IN' : 'CHECK_OUT', expires_at: expires,
    payload_json: JSON.stringify({ requested_at: nowIso, shift_id: active ? active.shift_id : null }),
  });
}

// LOCATION
const flow = dlg ? String(dlg.flow || '') : '';
if (flow !== 'CHECK_IN' && flow !== 'CHECK_OUT') return out('REPLY_ONLY', reply('Сейчас геолокация не запрашивалась. Нажмите «🟢 Начать работу» или «🔴 Завершить работу».', 'main_menu', { result: 'NO_REQUEST' }));
const exp = DateTime.fromISO(String(dlg.expires_at || ''));
if (!exp.isValid || exp < now) return out('CLEAR_REQUEST', reply('Время на отправку геолокации истекло. Нажмите кнопку ещё раз.', 'main_menu', { result: 'EXPIRED' }));
const loc = inp.location;
if (inp.is_forwarded) return out('REPLY_ONLY', reply('Пересланная геолокация не принимается. Отправьте свою текущую геолокацию кнопкой.', 'location', { result: 'FORWARDED' }));
if (!loc || !Number.isFinite(Number(loc.latitude)) || !Number.isFinite(Number(loc.longitude))) return out('REPLY_ONLY', reply('Не удалось прочитать геолокацию. Отправьте её кнопкой «📍 Отправить геолокацию».', 'location', { result: 'INVALID_LOCATION' }));
if (loc.live_period) return out('REPLY_ONLY', reply('Трансляция геопозиции не принимается. Отправьте обычную текущую геолокацию кнопкой.', 'location', { result: 'LIVE_LOCATION' }));
const nowSec = Math.floor(Date.now() / 1000);
if (!inp.message_date || nowSec - inp.message_date > 120) return out('REPLY_ONLY', reply('Геолокация устарела. Отправьте текущую геолокацию заново.', 'location', { result: 'STALE' }));
const lat = Number(loc.latitude);
const lon = Number(loc.longitude);
const dist = Math.round(haversine(lat, lon, LAT, LON));
if (dist > RADIUS) return out('REPLY_ONLY', reply('❌ Вы находитесь в ' + dist + ' м от рабочего места (допустимо ' + RADIUS + ' м). Подойдите ближе и отправьте геолокацию снова.', 'location', { result: 'OUTSIDE_RADIUS', distance_m: dist }));
const coords = lat.toFixed(6) + ',' + lon.toFixed(6);

if (flow === 'CHECK_IN') {
  if (byUpdate) return out('REPLY_ONLY', reply('Эта геолокация уже обработана.', 'main_menu', { result: 'DUPLICATE_UPDATE', status: 'WORKING', distance_m: dist }));
  if (active) return out('CLEAR_REQUEST', reply('У вас уже есть активная смена.', 'main_menu', { result: 'ALREADY_WORKING', distance_m: dist }));
  let cfg = {};
  try { cfg = JSON.parse((schedRow && schedRow.config_json) || emp.schedule_config || '{}') || {}; } catch (e) { cfg = {}; }
  const type = String(cfg.type || emp.schedule_type || '');
  let cls = 'NO_SCHEDULE';
  let dev = null;
  let sStart = '';
  let sEnd = '';
  const today = now.startOf('day');
  let offDay = false;
  if (type === '5/2') offDay = now.weekday >= 6;
  else if (type === '6/1') offDay = now.weekday === 7;
  else if (type === '2/2' && cfg.first_work_date) {
    const f = DateTime.fromFormat(String(cfg.first_work_date), 'dd.MM.yyyy', { zone: tz });
    if (f.isValid) { const dd = Math.floor(today.diff(f.startOf('day'), 'days').days); offDay = (((dd % 4) + 4) % 4) >= 2; }
  }
  if (type === 'Гибкий') cls = 'FLEXIBLE';
  else if (cfg.start && /^\d{2}:\d{2}$/.test(String(cfg.start))) {
    const hm = String(cfg.start).split(':').map(Number);
    const cands = [today.minus({ days: 1 }), today, today.plus({ days: 1 })].map(function (d) { return d.set({ hour: hm[0], minute: hm[1] }); });
    let best = cands[1];
    cands.forEach(function (c) { if (Math.abs(now.diff(c, 'minutes').minutes) < Math.abs(now.diff(best, 'minutes').minutes)) best = c; });
    dev = Math.round(now.diff(best, 'minutes').minutes);
    sStart = best.toISO();
    if (cfg.end && /^\d{2}:\d{2}$/.test(String(cfg.end))) {
      const he = String(cfg.end).split(':').map(Number);
      let e = best.set({ hour: he[0], minute: he[1] });
      if (e <= best) e = e.plus({ days: 1 });
      sEnd = e.toISO();
    }
    cls = dev > 0 ? 'LATE' : 'ON_TIME';
  }
  if (offDay && cls !== 'FLEXIBLE') cls = 'OFF_SCHEDULE_DAY';
  let clsText = '';
  if (cls === 'LATE') clsText = '\n⏰ Опоздание: ' + fmtMin(dev) + '. Смена всё равно начата.';
  else if (cls === 'ON_TIME') clsText = '\n👍 Вовремя.';
  else if (cls === 'OFF_SCHEDULE_DAY') clsText = '\nСегодня не рабочий день по вашему графику — смена записана как дополнительная.';
  const shift = {
    shift_id: uuidv4(), employee_id: emp.employee_id, telegram_id: inp.telegram_id,
    work_date: now.toFormat('yyyy-MM-dd'), scheduled_start: sStart, scheduled_end: sEnd,
    check_in_time: nowIso, check_in_coordinates: coords, distance_at_check_in: dist,
    shift_status: 'WORKING', schedule_deviation_minutes: dev, check_in_class: cls,
    coin_awarded: false, source_update_id: inp.update_id,
  };
  return out('CHECK_IN', reply('🟢 Смена начата в ' + now.toFormat('HH:mm') + ' (' + now.toFormat('dd.MM.yyyy') + ').\nРасстояние до рабочего места: ' + dist + ' м.' + clsText, 'main_menu', { result: 'CHECKED_IN', status: 'WORKING', distance_m: dist, check_in_class: cls }), { shift: shift });
}

// CHECK_OUT
if (!active) return out('CLEAR_REQUEST', reply('Активная смена не найдена.', 'main_menu', { result: 'NO_ACTIVE_SHIFT', distance_m: dist }));
const cin = DateTime.fromISO(String(active.check_in_time));
const minutes = cin.isValid ? Math.max(0, Math.round(now.diff(cin, 'minutes').minutes)) : 0;
const inGeoOk = !!active.check_in_coordinates && Number.isFinite(Number(active.distance_at_check_in));
return out('CHECK_OUT', reply('🔴 Смена завершена в ' + now.toFormat('HH:mm') + '.\nОтработано: ' + fmtMin(minutes) + '.\nРасстояние до рабочего места: ' + dist + ' м.', 'main_menu', { result: 'CHECKED_OUT', status: 'FINISHED', distance_m: dist }), {
  shift_id: active.shift_id, employee_id: emp.employee_id, work_date: active.work_date,
  check_out_time: nowIso, check_out_coordinates: coords, distance_at_check_out: dist,
  actual_duration_minutes: minutes, coin_eligible: inGeoOk,
  idempotency_key: 'SHIFT:' + emp.employee_id + ':' + active.work_date,
});

const d = $('Decide Action').first().json;
const r = Object.assign({}, d.reply);
let w = null;
try { w = $('Call Shift Ledger').first().json; } catch (e) { w = null; }
if (!w) {
  r.coin_result = d.coin_eligible ? 'ALREADY_AWARDED_TODAY' : 'NOT_ELIGIBLE';
  r.text += d.coin_eligible ? '\n🐟 Fish Coin за этот рабочий день уже начислен.' : '\nFish Coin не начислен: нет подтверждённой геопроверки при начале смены.';
} else {
  r.coin_result = w.result;
  if (w.result === 'APPLIED') r.text += '\n🐟 +1 Fish Coin! Баланс: ' + w.balance_after + '.';
  else if (w.result === 'DUPLICATE') r.text += '\n🐟 Fish Coin за этот рабочий день уже начислен.';
  else if (w.result === 'CAP_REACHED') r.text += '\n🐟 Достигнут максимум Fish Coins (' + w.max + ').';
  else r.text += '\nFish Coin не начислен (' + w.result + ').';
}
return [{ json: r }];
